class Cache
  def initialize(packer: nil)
    @packer = packer
    @store = {}
  end

  def write(key, payload, stale: false)
    if @packer
      packed_payload = @packer.dump(payload)
      @store[key] = { payload: packed_payload, stale: stale }
    else
      @store[key] = { payload: payload, stale: stale }
    end
  end

  def read(key)
    entry = @store[key]
    return nil unless entry

    if @packer
      @packer.load(entry[:payload])
    else
      entry[:payload]
    end
  end

  def sweep
    @store.reject! { |_key, entry| entry[:stale] }
  end
end
```

